from pydantic import BaseModel, Field, field_validator
class Pedido(BaseModel):
    item: str = Field(min_length=2)
    @field_validator("item")
    @classmethod
    def limpar(cls, v: str) -> str: return v.strip()
p = Pedido.model_validate({"item": "  Pizza  "})
print(p.model_dump())

